use pyo3::prelude::*;
use pyo3::types::{PyByteArray, PyBytes};
use pyo3::exceptions::PyValueError;

#[pyfunction]
fn convert<'py>(py: Python<'py>, raw: &Bound<'py, PyBytes>, width: usize, height: usize,
    crop: (usize,usize,usize,usize), mask: &Bound<'py, PyBytes>, intro: Option<(usize,usize,usize,usize)>)
    -> PyResult<Bound<'py, PyByteArray>> {
    let raw=raw.as_bytes(); let mask=mask.as_bytes();
    let (x0,y0,x1,y1)=crop;
    if width==0 || height==0 || width>16384 || height>16384 || x0>=x1 || y0>=y1 || x1>width || y1>height
        || raw.len()!=width*height*4 || mask.len()!=(x1-x0)*(y1-y0) {
        return Err(PyValueError::new_err("bad layout"));
    }
    let w=x1-x0; let h=y1-y0;
    if let Some((a,b,c,d))=intro {if a>=c || b>=d || c>w || d>h {return Err(PyValueError::new_err("bad intro"));}}
    PyByteArray::new_with(py,w*h*4,|out| {py.allow_threads(|| {
        for y in 0..h {
            let src=&raw[((y+y0)*width+x0)*4..((y+y0)*width+x1)*4];
            let dst=&mut out[y*w*4..(y+1)*w*4];
            let alpha=&mask[y*w..(y+1)*w];
            for ((s,d),a) in src.chunks_exact(4).zip(dst.chunks_exact_mut(4)).zip(alpha) {
                d[..3].copy_from_slice(&s[..3]); d[3]=*a;
            }
        }
        if let Some((a,b,c,d))=intro {
            let start=(b*w+a)*4; let key=[out[start],out[start+1],out[start+2]];
            for y in b..d {for x in a..c {
                let p=&mut out[(y*w+x)*4..(y*w+x+1)*4];
                let diff=p[..3].iter().zip(key).map(|(v,k)|v.abs_diff(k)).max().unwrap();
                let keyed=((diff.saturating_sub(4) as u16)*255/16).min(255) as u8;
                p[3]=p[3].min(keyed); if p[3]==0 {p[..3].fill(0);}
            }}
        }
    }); Ok(())})
}

#[pyfunction]
fn intro<'py>(py: Python<'py>, raw: &Bound<'py, PyBytes>)->PyResult<(Bound<'py, PyByteArray>, (u8,u8,u8), f64)> {
    let raw=raw.as_bytes();
    if raw.len()<4 || raw.len()%4!=0 {return Err(PyValueError::new_err("bad bytes"));}
    let key=(raw[0],raw[1],raw[2]); let mut zero=0usize;
    let result=PyByteArray::new_with(py,raw.len(),|out|{py.allow_threads(|| {
        for (src,dst) in raw.chunks_exact(4).zip(out.chunks_exact_mut(4)) {
            let diff=src[0].abs_diff(key.0).max(src[1].abs_diff(key.1)).max(src[2].abs_diff(key.2));
            let keyed=((diff.saturating_sub(4) as u16)*255/16).min(255) as u8;
            dst[3]=src[3].min(keyed);
            if dst[3]==0 {zero+=1;} else {dst[..3].copy_from_slice(&src[..3]);}
        }
    });Ok(())})?;
    Ok((result,key,zero as f64/(raw.len()/4) as f64))
}

#[pymodule]
fn overlay_poc(m: &Bound<'_, PyModule>)->PyResult<()> { m.add_function(wrap_pyfunction!(convert,m)?)?;m.add_function(wrap_pyfunction!(intro,m)?)?;Ok(()) }

