import json, statistics, sys, time
from pathlib import Path
import cv2
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'src-python'))
from models.overlay.overlay import DEFAULT_LAYOUT, MAX_LAYOUT, LAUNCHER, atlasMaskArray, regionRect
import overlay_poc
def introKeyAlpha(p,rect):
    a,b,c,d=rect;r=p[b:d,a:c];k=r[0,0,:3].astype(np.int32)
    diff=np.abs(r[...,:3].astype(np.int32)-k).max(axis=2)
    alpha=np.minimum(r[...,3],np.clip((diff-4)*255//16,0,255).astype(np.uint8))
    r[...,3]=alpha;r[alpha==0,:3]=0
    return tuple(int(v) for v in k),float(np.mean(alpha==0))
results=[]
for name,layout in [('default',DEFAULT_LAYOUT),('max',MAX_LAYOUT)]:
    for scale in [1,1.5,2]:
        w,h=(round(v*scale) for v in layout['atlas'])
        fw,fh=w+16,h+38
        raw=np.random.default_rng(7).integers(0,256,(fh,fw,4),dtype=np.uint8).tobytes()
        crop=(8,30,8+w,30+h)
        view=np.frombuffer(raw,np.uint8).reshape(fh,fw,4)[30:30+h,8:8+w]
        mask=atlasMaskArray((w,h),layout)
        for intro in [False,True]:
            rect=regionRect(LAUNCHER,(w,h),layout) if intro else None
            def old():
                p=view.copy(); p[...,3]=mask
                if intro: introKeyAlpha(p,rect)
                return p
            def cv():
                p=np.empty((h,w,4),np.uint8)
                cv2.mixChannels([view,mask],[p],[0,0,1,1,2,2,4,3])
                if intro: introKeyAlpha(p,rect)
                return p
            def rust():
                return np.frombuffer(overlay_poc.convert(raw,fw,fh,crop,mask.tobytes(),rect),np.uint8).reshape(h,w,4)
            funcs={'old':old,'cv2':cv,'rust':rust}
            expected=old()
            for f in funcs.values(): assert np.array_equal(f(),expected)
            timings={k:[] for k in funcs}
            for i in range(9):
                for k in (list(funcs) if i%2==0 else list(reversed(funcs))):
                    t=time.perf_counter_ns(); funcs[k](); timings[k].append((time.perf_counter_ns()-t)/1e6)
            r=dict(layout=name,scale=scale,size=(w,h),intro=intro,median_ms={k:statistics.median(v) for k,v in timings.items()},trials_ms=timings)
            results.append(r); print(json.dumps({k:v for k,v in r.items() if k!='trials_ms'}),flush=True)
Path(__file__).with_name('result.json').write_text(json.dumps(results,indent=2))
